using MedInsights.Lib.Authorization;
using MedInsights.Repositories.Interfaces;
using TurnKeyOps.Lib.Dtos;
using TurnKeyOps.Lib.Utils;
using TurnKeyOps.Repositories.Interfaces;
namespace TurnKeyOps.Services;
// Payroll reads operational references directly in the tenant partition, not through Finance/Jobs permission checks.
public sealed class PayrollService(IPayrollStore store,IPayrollAuthority authority,IUserContext user,ITenantMembershipRepository memberships,IJobRepository jobs,ICalendarEventRepository calendar)
{
    async Task Need(string permission,CancellationToken ct){if(!await authority.AllowsAsync(permission,ct))throw new MedInsights.Lib.ForbiddenAccessException("Required action grant: "+permission);}
    public async Task<object> ReadAsync(CancellationToken ct=default)
    {
        await authority.RequireAsync(false,ct);var s=await store.ReadAsync(user.TenantId,ct);var admin=await authority.AllowsAsync("time.approve",ct);var crewAccess=await authority.AllowsAsync("time.crew",ct);var compensation=await authority.AllowsAsync("payroll.compensation.read",ct);var ownCrews=s.Crews.Where(c=>c.LeadId==user.UserId).ToArray();
        bool Visible(Guid employee)=>admin||employee==user.UserId||crewAccess&&ownCrews.Any(c=>c.Members.Contains(employee));
        var time=s.Time.Where(t=>Visible(t.EmployeeId)).ToArray();var partition=RepositoryKeyHelper.ToTenantPartitionKey(user.TenantId);
        var active=(await memberships.GetActiveAssignedByTenantAsync(user.TenantId,ct)).Where(m=>m.TenantId==user.TenantId&&UserModulePermissions.IsActive(m)).ToArray();
        var grants=new Dictionary<string,bool>();foreach(var a in UserModulePermissions.PayrollActions)grants[a]=await authority.AllowsAsync(a,ct);
        var jobChoices=s.Configuration.Enabled&&s.Configuration.UsesJobs?(await jobs.ListAsync(partition,ct)).Where(j=>j.PartitionKey==partition&&!j.IsDeleted).Select(j=>new{j.Id,j.Name}).ToArray():[];
        var today=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById(s.Configuration.Timezone)).DateTime);
        var schedule=s.Configuration.Enabled&&s.Configuration.UsesScheduling?(await calendar.ListAsync(partition,ct)).Where(e=>e.PartitionKey==partition&&!e.IsDeleted&&e.EventStatus!="cancelled"&&DateOnly.FromDateTime(TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(e.StartUtc,DateTimeKind.Utc),TimeZoneInfo.FindSystemTimeZoneById(s.Configuration.Timezone)))<=today&&DateOnly.FromDateTime(TimeZoneInfo.ConvertTimeFromUtc(DateTime.SpecifyKind(e.EndUtc,DateTimeKind.Utc),TimeZoneInfo.FindSystemTimeZoneById(s.Configuration.Timezone)))>=today&&active.Any(m=>Visible(m.UserId)&&(e.MembershipIds.Contains(m.Id)||e.AssignedTechnicianMembershipId==m.Id))).Select(e=>new{e.Id,e.JobId,e.Title,e.StartUtc,e.EndUtc}).ToArray():[];
        var preview=JobConfigurationService.Clone(s);preview.Time=preview.Time.Where(t=>t.Status!="ACTIVE").Select(t=>t.Status is "DRAFT" or "SUBMITTED" or "NEEDS_REVIEW"?t with{Status="APPROVED"}:t).ToList();
        var earningsPreview=PayrollEngine.Calculate(preview,new(Guid.Empty,new(1900,1,1),new(9998,12,31),new(9998,12,31),DateTimeOffset.UtcNow),false).Where(l=>Visible(l.EmployeeId)).Select(l=>new{l.TimeId,l.EmployeeId,l.Date,l.Type,l.Hours}).ToArray();
        return new{s.Version,s.Configuration,EarningsPreview=earningsPreview,EmployeeId=user.UserId,Grants=grants,Time=time,Crews=admin?s.Crews.ToArray():ownCrews,Employees=active.Where(m=>Visible(m.UserId)).Select(m=>new{EmployeeId=m.UserId,membershipId=m.Id}),Jobs=jobChoices,Schedule=schedule,Periods=s.Periods.ToArray(),Profiles=compensation?s.Profiles.ToArray():[],Batches=compensation?s.Batches.ToArray():[],Actuals=compensation?s.Actuals.ToArray():[],Leave=s.Leave.Where(l=>Visible(l.EmployeeId)).ToArray(),WageRequirements=compensation?s.WageRequirements.ToArray():[],Exceptions=time.Select(t=>new{t.Id,Issues=PayrollEngine.Exceptions(s,t)}).Where(t=>t.Issues.Length>0).ToArray(),Reconciliation=compensation?s.Batches.Select(b=>new{b.Id,Issues=PayrollEngine.Reconcile(s,b)}).ToArray():[],Reports=new{ByEmployee=time.Where(t=>t.Status is not("VOID" or "CORRECTED" or "REJECTED")).GroupBy(t=>t.EmployeeId).Select(g=>new{EmployeeId=g.Key,Hours=g.Sum(t=>t.Hours)}),ByJob=time.Where(t=>t.Status is "APPROVED" or "EXPORTED").GroupBy(t=>t.JobId).Select(g=>new{JobId=g.Key,Hours=g.Sum(t=>t.Hours)}),ByCostCode=time.Where(t=>t.Status is "APPROVED" or "EXPORTED").GroupBy(t=>t.CostCode).Select(g=>new{CostCode=g.Key,Hours=g.Sum(t=>t.Hours)}),ByTrade=time.Where(t=>t.Status is "APPROVED" or "EXPORTED").GroupBy(t=>t.Trade).Select(g=>new{Trade=g.Key,Hours=g.Sum(t=>t.Hours)})}};
    }
    public async Task<object> CommandAsync(PayrollCommand c,CancellationToken ct=default)
    {
        await authority.RequireAsync(true,ct);var s=await store.ReadAsync(user.TenantId,ct);
        var grant=c.Action switch{"configure" or "crew" or "period" or "review-period" or "close-period" or "reopen-period" or "wage-requirement"=>"payroll.admin","profile"=>"payroll.compensation.read","approve" or "reject" or "approve-leave" or "reject-leave"=>"time.approve","prepare" or "void-batch"=>"payroll.prepare","export"=>"payroll.export","import-results" or "correct-result" or "reconcile"=>"payroll.results","crew-time"=>"time.crew","import-time"=>"payroll.admin",_=>"time.self"};await Need(grant,ct);
        if(c.Action is "prepare" or "void-batch" or "export" or "import-results" or "correct-result" or "reconcile" or "profile" or "wage-requirement")await Need("payroll.compensation.read",ct);
        var fingerprint=PayrollEngine.Hash(new{c.Id,c.Action,c.TargetId,c.Reason,c.At,c.Configuration,c.Time,c.Entries,c.Profile,c.Crew,c.Period,c.Leave,c.WageRequirement,c.Actuals,c.BreakKind});
        var old=s.Audit.SingleOrDefault(a=>a.CommandId==c.Id);if(old!=null){if(old.Actor!=user.UserId.ToString("D")||old.Fingerprint!=fingerprint)throw new ArgumentException("Command identity conflicts with prior content.");return new{s.Version,Replayed=true};}
        if(s.Version!=c.ExpectedVersion)throw new InvalidOperationException("Payroll changed. Refresh and resolve the conflict.");
        var target=s.Time.SingleOrDefault(t=>t.Id==c.TargetId);var targetLeave=s.Leave.SingleOrDefault(l=>l.Id==c.TargetId);
        var approve=await authority.AllowsAsync("time.approve",ct);var crewWrite=await authority.AllowsAsync("time.crew",ct);
        bool MayAct(Guid employee)=>employee==user.UserId||approve||crewWrite&&s.Crews.Any(cr=>cr.LeadId==user.UserId&&cr.Members.Contains(employee));
        var ids=new[]{c.Time?.EmployeeId,target?.EmployeeId,c.Profile?.EmployeeId,c.Leave?.EmployeeId,targetLeave?.EmployeeId}.Where(v=>v!=null).Select(v=>v!.Value).Concat(c.Entries.Select(t=>t.EmployeeId)).Concat(c.Crew?.Members??[]).Concat(c.Crew==null?[]:new[]{c.Crew.LeadId}).Distinct().ToArray();
        var active=(await memberships.GetActiveAssignedByTenantAsync(user.TenantId,ct)).Where(m=>m.TenantId==user.TenantId&&UserModulePermissions.IsActive(m)).Select(m=>m.UserId).ToHashSet();
        foreach(var employee in ids){if(!active.Contains(employee)&&!(approve&&target?.EmployeeId==employee&&c.Action is "approve" or "reject" or "correct" or "adjustment"))throw new ArgumentException("Employee must be an active tenant member or an authorized historical-time review.");if(c.Action is not("profile" or "crew" or "import-results" or "correct-result" or "import-time")&&!MayAct(employee))throw new MedInsights.Lib.ForbiddenAccessException("Employee is outside your authorized crew.");}
        if(c.Action=="crew-time"&&!approve&&s.Crews.SingleOrDefault(cr=>cr.Id==c.TargetId)?.LeadId!=user.UserId)throw new MedInsights.Lib.ForbiddenAccessException("Only the assigned crew lead may enter crew time.");
        var partition=RepositoryKeyHelper.ToTenantPartitionKey(user.TenantId);
        var timeInputs=c.Entries.Concat(c.Time==null?[]:new[]{c.Time}).ToArray();
        foreach(var t in timeInputs){if(t.JobId is Guid job){if(!s.Configuration.UsesJobs)throw new ArgumentException("Jobs integration is disabled.");if(await jobs.GetAsync(partition,RepositoryKeyHelper.ToRowKey(job),ct) is not {IsDeleted:false} found||found.Id!=job||found.PartitionKey!=partition)throw new ArgumentException("Job not found in tenant.");if(t.SiteId!=null&&found.JobSiteId!=t.SiteId)throw new ArgumentException("Job/site mismatch.");}
            if(t.ScheduleEventId is Guid scheduleId){if(!s.Configuration.UsesScheduling)throw new ArgumentException("Scheduling integration disabled.");var ev=await calendar.GetAsync(partition,RepositoryKeyHelper.ToRowKey(scheduleId),ct);if(ev==null||ev.IsDeleted||ev.PartitionKey!=partition||ev.JobId!=t.JobId)throw new ArgumentException("Schedule allocation does not match Job.");}}
        if(c.WageRequirement!=null&&await jobs.GetAsync(partition,RepositoryKeyHelper.ToRowKey(c.WageRequirement.JobId),ct) is not {IsDeleted:false})throw new ArgumentException("Prevailing wage Job not found.");
        // Clone before applying: a failed multi-employee import never commits a partial operation.
        var next=JobConfigurationService.Clone(s);PayrollEngine.Apply(next,c,user.UserId.ToString("D"),DateTimeOffset.UtcNow);next.Audit.Add(new(c.Id,c.Action,fingerprint,user.UserId.ToString("D"),DateTimeOffset.UtcNow,c.Reason));PayrollIntegrity.ValidateTransition(s,next);await store.SaveAsync(user.TenantId,next,c.ExpectedVersion,ct);return new{Version=(await store.ReadAsync(user.TenantId,ct)).Version,Replayed=false};
    }
    public async Task<string> ExportAsync(Guid batchId,CancellationToken ct=default){await authority.RequireAsync(false,ct);await Need("payroll.export",ct);await Need("payroll.compensation.read",ct);var s=await store.ReadAsync(user.TenantId,ct);if(!s.Configuration.Enabled)throw new ArgumentException("Payroll disabled.");var b=s.Batches.SingleOrDefault(b=>b.Id==batchId)??throw new ArgumentException("Batch not found.");return b.Artifact??throw new ArgumentException("Export must be approved first.");}
    public async Task<object> ReadinessAsync(CancellationToken ct=default){await authority.RequireAsync(false,ct);var result=System.Text.Json.JsonSerializer.SerializeToElement(await ReadAsync(ct),JobConfigurationService.Json);return new{Title="Payroll readiness",Exceptions=result.GetProperty("exceptions"),Time=result.GetProperty("time").EnumerateArray().Select(t=>new{Id=t.GetProperty("id"),Employee=t.GetProperty("employeeId"),Status=t.GetProperty("status"),Hours=t.GetProperty("hours")}),Action="Review source entries and resolve exceptions. Bob has made no changes."};}
}
